<?php
/** Immutable version history and explicit Study bindings, on disposable M0 only. */
define('DOING_CRON',true);require __DIR__.'/m0/bootstrap.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Owner.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/builder.php';
use EIPSI\AssessmentEditor\Repository as R;use EIPSI\AssessmentEditor\Definition as D;use EIPSI\StudyEngine\Builder as B;
$tests=0;$failed=0;$owner=new EIPSI\AssessmentEditor\Runtime\Owner();$owner->store->install();$id='AE_HISTORY_'.bin2hex(random_bytes(8));$study=null;$service=new B\Service(new EIPSI\StudyEngine\Persistence\Database($wpdb));
function hv_assert($value,$message='Version assertion failed'){if(!$value)throw new RuntimeException($message);}
function hv_case($name,$fn){global $tests,$failed;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}
try{
$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']=$id;$d['title']='Primera versión';$r=R::save($d,0);$one=$owner->publish($id,$r['revision']);$d=$r['definition'];$d['title']='Segunda versión';$d['elements'][0]['properties']['label_html']='<p>Pregunta actualizada</p>';$r=R::save($d,$r['revision']);$two=$owner->publish($id,$r['revision']);
hv_case('History lists every immutable publication newest first with distinct version and author revision',function()use($id,$one,$two){$v=R::versions($id);hv_assert(count($v)===2&&$v[0]['id']===$two['version_id']&&$v[0]['number']===2&&$v[1]['id']===$one['version_id']&&$v[1]['author_revision']===1);});
hv_case('Opening an old publication returns its exact content without replacing the draft',function()use($id,$one){$before=R::load($id);$v=R::loadVersion($id,$one['version_id']);hv_assert($v['read_only']&&$v['definition']['title']==='Primera versión');hv_assert(D::json($before)===D::json(R::load($id)));hv_assert($v['version']['definition_hash']===$one['definition_hash']);});
hv_case('Version lookup rejects a version belonging to another assessment and enforces authorization',function()use($id,$one){try{R::loadVersion('AE_OTHER',$one['version_id']);throw new RuntimeException('Cross-assessment leak');}catch(Throwable $e){hv_assert($e->getCode()===404);}wp_set_current_user(0);try{R::versions($id);throw new RuntimeException('Unauthorized history');}catch(Throwable $e){hv_assert($e->getCode()===403);}finally{wp_set_current_user(1);}});
hv_case('Study catalog distinguishes versions and retains the exact question snapshot for each',function()use($service,$id,$one,$two){$v=array_values(array_filter($service->nativeTemplates(),static function($t)use($id){return $t['assessment_id']===$id;}));hv_assert(count($v)===2&&$v[0]['id']===$two['version_id']&&$v[1]['id']===$one['version_id']);hv_assert($v[0]['number']===2&&$v[1]['number']===1&&$v[0]['hash']!==$v[1]['hash']);hv_assert(strpos($v[1]['edit_url'],'version='.$one['version_id'])!==false);});
hv_case('Saving a Study pins the explicitly chosen old version and updating the draft selects the new snapshot',function()use($service,&$study,$one,$two,$id){$study=$service->create(array('name'=>'Historial'),'HISTORY_CREATE_'.bin2hex(random_bytes(6)));$d=$study['definition'];$n=B\Draft::block('E_HISTORY',$d['id'],$d['root_block_ids'][0],'MICRO',0);$n['schedule']=B\Draft::schedule();$n['metadata']['native_version_id']=$one['version_id'];$d['nodes'][]=$n;$study=$service->save($study['id'],0,'HISTORY_SAVE_1',$d);$nodes=array_column($study['definition']['nodes'],null,'id');hv_assert($nodes['E_HISTORY']['metadata']['native_definition_hash']===$one['definition_hash']);$d=$study['definition'];foreach($d['nodes'] as &$node)if($node['id']==='E_HISTORY')$node['metadata']['native_version_id']=$two['version_id'];unset($node);$study=$service->save($study['id'],$study['revision'],'HISTORY_SAVE_2',$d);$nodes=array_column($study['definition']['nodes'],null,'id');hv_assert($nodes['E_HISTORY']['metadata']['native_definition_hash']===$two['definition_hash']);hv_assert(R::loadVersion($id,$one['version_id'])['definition']['title']==='Primera versión');});
hv_case('History AJAX requires a valid nonce and returns scoped published content with a valid nonce',function()use($id,$one){$bad=m0_http('/wp-admin/admin-ajax.php',array('action'=>'eipsi_assessment_editor','nonce'=>'invalid','operation'=>'load_version','id'=>$id,'version_id'=>$one['version_id']),true);hv_assert(wp_remote_retrieve_response_code($bad)===403);$ok=m0_http('/wp-admin/admin-ajax.php',array('action'=>'eipsi_assessment_editor','nonce'=>m0_admin_nonce('eipsi_native_assessment'),'operation'=>'load_version','id'=>$id,'version_id'=>$one['version_id']),true);$j=json_decode(wp_remote_retrieve_body($ok),true);hv_assert(wp_remote_retrieve_response_code($ok)===200&&$j['success']&&$j['data']['read_only']&&$j['data']['definition']['title']==='Primera versión');});
}finally{wp_set_current_user(1);if($study)$service->deleteStudy($study['study_id'],'ELIMINAR '.$study['study_id']);$owner->store->db->query($owner->store->prepare('DELETE FROM '.$owner->store->table('versions').' WHERE assessment_id=%s',$id));delete_option(R::PREFIX.$id);}
echo "$tests tests, $failed failures\n";exit($failed?1:0);
